package io.github.hoangtnedu.java;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;
@WebServlet(urlPatterns={"/students","/admin/panel","/staff/panel","/user/profile"}) public class StudentServlet extends HttpServlet {
 protected void doGet(HttpServletRequest q,HttpServletResponse r)throws ServletException,IOException{try{q.setAttribute("students",AppState.store.list(q.getParameter("q")==null?"":q.getParameter("q")));if(q.getParameter("id")!=null)q.setAttribute("edit",AppState.store.get(Long.parseLong(q.getParameter("id"))));q.getRequestDispatcher("/WEB-INF/students.jsp").forward(q,r);}catch(RuntimeException ex){r.sendError(400);}}
 protected void doPost(HttpServletRequest q,HttpServletResponse r)throws IOException{try{if("delete".equals(q.getParameter("action")))AppState.store.delete(Long.parseLong(q.getParameter("id")));else{Student s=new Student(q.getParameter("code"),q.getParameter("name"),q.getParameter("email"),q.getParameter("className"));String id=q.getParameter("id");if(id!=null&&!id.isBlank())s.setId(Long.parseLong(id));AppState.store.save(s);}r.sendRedirect(q.getContextPath()+"/students");}catch(RuntimeException ex){r.sendError(400,"Du lieu khong hop le hoac trung ma");}}
}